:root {
  --color-bg: #1a1a2e;
  --color-surface: #16213e;
  --color-primary: #e94560;
  --color-secondary: #0f3460;
  --color-text: #eaeaea;
  --color-text-muted: #a0a0b0;
  --color-success: #4ecca3;
  --color-danger: #ff6b6b;
  --radius: 12px;
  --spacing: 1rem;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 2rem 1rem;
  line-height: 1.5;
}

.app {
  width: 100%;
  max-width: 640px;
}

.app-title {
  font-size: 1.75rem;
  text-align: center;
  margin-bottom: 1.5rem;
  color: var(--color-primary);
  letter-spacing: 0.05em;
}

.panel {
  background: var(--color-surface);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.hidden {
  display: none !important;
}

.field {
  margin-bottom: 1rem;
}

label {
  display: block;
  margin-bottom: 0.35rem;
  font-weight: 600;
  color: var(--color-text);
}

input, select {
  width: 100%;
  padding: 0.65rem 0.75rem;
  font-size: 1rem;
  font-family: var(--font);
  border: 2px solid var(--color-secondary);
  border-radius: 8px;
  background: var(--color-bg);
  color: var(--color-text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus, select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.btn {
  display: inline-block;
  padding: 0.7rem 1.25rem;
  font-size: 1rem;
  font-family: var(--font);
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  text-align: center;
}

.btn:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background: var(--color-primary);
  color: #fff;
}

.btn-primary:hover {
  background: #c73a52;
}

.btn-secondary {
  background: var(--color-secondary);
  color: var(--color-text);
}

.btn-secondary:hover {
  background: #1a4a7a;
}

.btn-yes {
  background: var(--color-success);
  color: #0a2a20;
}

.btn-yes:hover {
  background: #3db88a;
}

.btn-no {
  background: var(--color-danger);
  color: #2a0a0a;
}

.btn-no:hover {
  background: #e05555;
}

.btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

#add-btn {
  width: 100%;
  margin-bottom: 1.25rem;
}

.card-list-wrapper {
  margin-bottom: 1.25rem;
}

.section-heading {
  font-size: 1.15rem;
  margin-bottom: 0.75rem;
  color: var(--color-text-muted);
  font-weight: 600;
}

.card-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.card-list li {
  background: var(--color-bg);
  border-left: 4px solid var(--color-primary);
  border-radius: 6px;
  padding: 0.65rem 0.75rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.95rem;
}

.card-list .answer-badge {
  font-size: 0.8rem;
  font-weight: 700;
  padding: 0.15rem 0.5rem;
  border-radius: 4px;
  text-transform: uppercase;
  white-space: nowrap;
}

.answer-badge.yes {
  background: var(--color-success);
  color: #0a2a20;
}

.answer-badge.no {
  background: var(--color-danger);
  color: #2a0a0a;
}

.empty-message {
  color: var(--color-text-muted);
  font-style: italic;
  font-size: 0.95rem;
  padding: 0.5rem 0;
}

#play-btn {
  width: 100%;
}

.quiz-progress {
  font-size: 0.95rem;
  color: var(--color-text-muted);
  margin-bottom: 1rem;
  text-align: center;
  font-weight: 600;
}

.quiz-card {
  text-align: center;
  padding: 1rem 0;
}

.quiz-question {
  font-size: 1.3rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
  min-height: 2.5em;
}

.quiz-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

.quiz-actions .btn {
  flex: 1;
  max-width: 160px;
  padding: 0.9rem;
  font-size: 1.1rem;
}

.score-screen {
  text-align: center;
  padding: 1rem 0;
}

.score-screen h2 {
  color: var(--color-success);
  font-size: 1.5rem;
  margin-bottom: 0.75rem;
}

.score-text {
  font-size: 1.2rem;
  margin-bottom: 1.5rem;
}

.score-actions {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-width: 280px;
  margin: 0 auto;
}

@media (min-width: 480px) {
  .score-actions {
    flex-direction: row;
    max-width: none;
    justify-content: center;
  }
  .score-actions .btn {
    flex: 1;
    max-width: 160px;
  }
}

@media (max-width: 360px) {
  body {
    padding: 1rem 0.5rem;
  }
  .panel {
    padding: 1rem;
  }
  .app-title {
    font-size: 1.4rem;
  }
  .quiz-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .quiz-actions .btn {
    max-width: none;
  }
}

// Pixel Quiz Maker

const state = {
  cards: [],
  currentIndex: 0,
  correctCount: 0,
  inPlayMode: false
};

// DOM references
const creationPanel = document.getElementById('creation-panel');
const playPanel = document.getElementById('play-panel');
const cardForm = document.getElementById('card-form');
const questionInput = document.getElementById('question-input');
const answerSelect = document.getElementById('answer-select');
const cardList = document.getElementById('card-list');
const emptyMessage = document.getElementById('empty-message');
const playBtn = document.getElementById('play-btn');
const quizProgress = document.getElementById('quiz-progress');
const quizCard = document.getElementById('quiz-card');
const quizQuestion = document.getElementById('quiz-question');
const answerYes = document.getElementById('answer-yes');
const answerNo = document.getElementById('answer-no');
const scoreScreen = document.getElementById('score-screen');
const scoreText = document.getElementById('score-text');
const restartBtn = document.getElementById('restart-btn');
const backBtn = document.getElementById('back-btn');

// --- Card creation ---

function renderCards() {
  cardList.innerHTML = '';
  if (state.cards.length === 0) {
    emptyMessage.classList.remove('hidden');
    playBtn.disabled = true;
    return;
  }
  emptyMessage.classList.add('hidden');
  playBtn.disabled = false;

  state.cards.forEach((card, index) => {
    const li = document.createElement('li');
    const text = document.createElement('span');
    text.textContent = `${index + 1}. ${card.question}`;
    const badge = document.createElement('span');
    badge.className = `answer-badge ${card.answer}`;
    badge.textContent = card.answer;
    li.appendChild(text);
    li.appendChild(badge);
    cardList.appendChild(li);
  });
}

function handleAddCard(e) {
  e.preventDefault();
  const question = questionInput.value.trim();
  const answer = answerSelect.value;
  if (!question || !answer) return;

  state.cards.push({ question, answer });
  questionInput.value = '';
  answerSelect.value = '';
  questionInput.focus();
  renderCards();
}

// --- Play mode ---

function startQuiz() {
  if (state.cards.length === 0) return;
  state.inPlayMode = true;
  state.currentIndex = 0;
  state.correctCount = 0;
  creationPanel.classList.add('hidden');
  playPanel.classList.remove('hidden');
  scoreScreen.classList.add('hidden');
  quizCard.classList.remove('hidden');
  showQuestion();
}

function showQuestion() {
  if (state.currentIndex >= state.cards.length) {
    showScore();
    return;
  }
  const card = state.cards[state.currentIndex];
  quizQuestion.textContent = card.question;
  quizProgress.textContent = `Question ${state.currentIndex + 1} of ${state.cards.length}`;
}

function handleAnswer(userAnswer) {
  if (!state.inPlayMode) return;
  const card = state.cards[state.currentIndex];
  if (userAnswer === card.answer) {
    state.correctCount++;
  }
  state.currentIndex++;
  showQuestion();
}

function showScore() {
  quizCard.classList.add('hidden');
  scoreScreen.classList.remove('hidden');
  quizProgress.textContent = '';
  scoreText.textContent = `You got ${state.correctCount} out of ${state.cards.length} correct!`;
}

function restartQuiz() {
  state.currentIndex = 0;
  state.correctCount = 0;
  scoreScreen.classList.add('hidden');
  quizCard.classList.remove('hidden');
  showQuestion();
}

function backToEditor() {
  state.inPlayMode = false;
  playPanel.classList.add('hidden');
  creationPanel.classList.remove('hidden');
  renderCards();
}

// --- Event listeners ---

cardForm.addEventListener('submit', handleAddCard);
playBtn.addEventListener('click', startQuiz);
answerYes.addEventListener('click', () => handleAnswer('yes'));
answerNo.addEventListener('click', () => handleAnswer('no'));
restartBtn.addEventListener('click', restartQuiz);
backBtn.addEventListener('click', backToEditor);

// Initial render
renderCards();
